begin;
select '1..5';
do $$declare root_user uuid:=gen_random_uuid(); viewer uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); org uuid:=gen_random_uuid(); member_id uuid; result jsonb; role_id uuid; assignments jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(root_user,root_user||'@platform.test',now()),(viewer,viewer||'@platform.test',now()),(outsider,outsider||'@platform.test',now());
 update public.profiles set role='super_admin' where id=root_user;
 insert into public.organizers(id,user_id,name,email,status) values(org,outsider,'Tenant',outsider||'@platform.test','active');
 assert public.platform_has_permission(root_user,'platform_users.invite'), 'root keeps access';
 assert not public.platform_has_permission(outsider,'platform_users.invite'), 'tenant ownership grants no platform authority';
 select id into role_id from public.platform_roles where key='finance';
 assignments:=jsonb_build_array(jsonb_build_object('roleId',role_id,'eventId',null));
 result:=public.platform_manage(root_user,'invitations.create',jsonb_build_object('email',viewer||'@platform.test','tokenHash',repeat('a',64),'assignments',assignments));
 begin perform public.platform_accept_invitation(outsider,repeat('a',64));raise exception 'wrong email accepted';exception when others then if sqlerrm<>'IAM_INVITATION_IDENTITY' then raise;end if;end;
 result:=public.platform_accept_invitation(viewer,repeat('a',64));member_id:=(result->>'memberId')::uuid;
 assert public.platform_has_permission(viewer,'platform_finance.read'), 'finance reader can read';
 assert not public.platform_has_permission(viewer,'platform_payouts.execute'), 'finance reader cannot transfer';
 assert not public.iam_has_permission(viewer,org,'finance.read'), 'platform membership grants no tenant authority';
 assert (select role from public.profiles where id=viewer)='attendee', 'identity global role remains unchanged';
 begin perform public.platform_accept_invitation(viewer,repeat('a',64));raise exception 'token reused';exception when others then if sqlerrm<>'IAM_INVITATION_INVALID' then raise;end if;end;
 perform public.platform_manage(root_user,'members.update',jsonb_build_object('id',member_id,'status','suspended','assignments',assignments));
 assert not public.platform_has_permission(viewer,'platform_finance.read'), 'suspension is immediate';
 assert exists(select 1 from public.audit_logs where actor_id=root_user and action='platform_iam.members.update' and after_data->>'status'='suspended'), 'mutation audited';
 begin perform public.platform_manage(root_user,'members.remove',jsonb_build_object('id',root_user));raise exception 'root removed';exception when others then if sqlerrm<>'IAM_OWNER_PROTECTED' then raise;end if;end;
end$$;
select 'ok 1 - platform access, organization isolation, invites and suspension';
do $$declare root_user uuid:=gen_random_uuid(); delegate uuid:=gen_random_uuid(); recipient uuid:=gen_random_uuid(); role_id uuid; member_id uuid; result jsonb; assignments jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(root_user,root_user||'@platform.test',now()),(delegate,delegate||'@platform.test',now()),(recipient,recipient||'@platform.test',now());
 update public.profiles set role='super_admin' where id=root_user;
 result:=public.platform_manage(root_user,'roles.create','{"name":"Limited test delegate","permissions":["platform_users.invite","platform_roles.create","platform_organizers.read"]}');role_id:=(result->>'id')::uuid;
 insert into public.platform_members(user_id) values(delegate) returning id into member_id;
 insert into public.platform_role_assignments(member_id,role_id) values(member_id,role_id);
 begin perform public.platform_manage(delegate,'roles.create','{"name":"Escalation","permissions":["platform_payouts.execute"]}');raise exception 'escalation';exception when others then if sqlerrm<>'IAM_CANNOT_DELEGATE' then raise;end if;end;
 result:=public.platform_manage(root_user,'roles.create','{"name":"Read only fixture","permissions":["platform_organizers.read"]}');
 assignments:=jsonb_build_array(jsonb_build_object('roleId',result->>'id','eventId',null));
 perform public.platform_manage(delegate,'invitations.create',jsonb_build_object('email',recipient||'@platform.test','tokenHash',repeat('b',64),'assignments',assignments));
 perform public.platform_manage(root_user,'roles.update',jsonb_build_object('id',role_id,'name','Limited test delegate','permissions',jsonb_build_array('platform_users.invite')));
 begin perform public.platform_accept_invitation(recipient,repeat('b',64));raise exception 'stale inviter authority';exception when others then if sqlerrm<>'IAM_CANNOT_DELEGATE' then raise;end if;end;
 assert not exists(select 1 from public.platform_members where user_id=recipient), 'failed acceptance atomic';
 begin perform public.platform_manage(root_user,'roles.delete',jsonb_build_object('id',role_id));raise exception 'assigned role removed';exception when others then if sqlerrm<>'IAM_ROLE_IN_USE' then raise;end if;end;
end$$;
select 'ok 2 - delegation, custom roles, stale invites and atomicity';
do $$declare root_user uuid:=gen_random_uuid(); recipient uuid:=gen_random_uuid(); role_id uuid; result jsonb; invite_id uuid; assignments jsonb; member_id uuid;
begin
 insert into auth.users(id,email,email_confirmed_at) values(root_user,root_user||'@platform.test',now()),(recipient,recipient||'@platform.test',now());
 update public.profiles set role='super_admin' where id=root_user;
 select id into role_id from public.platform_roles where key='support';assignments:=jsonb_build_array(jsonb_build_object('roleId',role_id,'eventId',null));
 result:=public.platform_manage(root_user,'invitations.create',jsonb_build_object('email',recipient||'@platform.test','tokenHash',repeat('c',64),'assignments',assignments));invite_id:=(result->>'id')::uuid;
 update public.platform_invitations set expires_at=now()-interval '1 second' where id=invite_id;
 begin perform public.platform_accept_invitation(recipient,repeat('c',64));raise exception 'expired accepted';exception when others then if sqlerrm<>'IAM_INVITATION_INVALID' then raise;end if;end;
 perform public.platform_manage(root_user,'invitations.resend',jsonb_build_object('id',invite_id,'tokenHash',repeat('d',64)));
 begin perform public.platform_accept_invitation(recipient,repeat('c',64));raise exception 'old token accepted';exception when others then if sqlerrm<>'IAM_INVITATION_INVALID' then raise;end if;end;
 result:=public.platform_accept_invitation(recipient,repeat('d',64));member_id:=(result->>'memberId')::uuid;
 perform public.platform_manage(root_user,'invitations.create',jsonb_build_object('email',recipient||'@platform.test','tokenHash',repeat('e',64),'assignments',assignments));
 perform public.platform_manage(root_user,'members.remove',jsonb_build_object('id',member_id));
 begin perform public.platform_accept_invitation(recipient,repeat('e',64));raise exception 'old invite restored removed access';exception when others then if sqlerrm<>'IAM_INVITATION_INVALID' then raise;end if;end;
 assert not public.platform_has_permission(recipient,'platform_organizers.read'), 'removed access revoked';
 update public.profiles set status='suspended' where id=root_user;
 assert not public.platform_has_permission(root_user,'platform_users.invite'), 'suspended roots denied';
 assert not exists(select 1 from public.audit_logs where actor_id=root_user and (before_data::text like '%token_hash%' or after_data::text like '%token_hash%')), 'no token hashes in audit';
end$$;
select 'ok 3 - expiry, rotation, removal, profile suspension and token privacy';
do $$declare t text;begin
 foreach t in array array['platform_permissions','platform_roles','platform_role_permissions','platform_members','platform_role_assignments','platform_invitations'] loop
  assert (select relrowsecurity from pg_class where oid=('public.'||t)::regclass), 'RLS required';
  assert not has_table_privilege('authenticated','public.'||t,'SELECT,INSERT,UPDATE,DELETE'), 'browser cannot access IAM';
  assert not has_table_privilege('anon','public.'||t,'SELECT,INSERT,UPDATE,DELETE'), 'anonymous denied';
 end loop;
 assert not has_function_privilege('authenticated','public.platform_manage(uuid,text,jsonb)','EXECUTE'), 'mutation RPC server only';
 assert not has_function_privilege('authenticated','public.platform_accept_invitation(uuid,text)','EXECUTE'), 'accept RPC server only';
 assert not has_function_privilege('anon','public.platform_access_context(uuid)','EXECUTE'), 'access RPC server only';
end$$;
select 'ok 4 - RLS and function grants';
do $$declare root_user uuid:=gen_random_uuid(); result jsonb; role_id uuid;begin
 insert into auth.users(id,email) values(root_user,root_user||'@platform.test');update public.profiles set role='super_admin' where id=root_user;
 begin perform public.platform_manage(root_user,'roles.create','{"name":"Tenant injection","permissions":["users.invite"]}');raise exception 'tenant permissions accepted';exception when others then if sqlerrm<>'IAM_CANNOT_DELEGATE' then raise;end if;end;
 result:=public.platform_manage(root_user,'roles.create','{"name":"Temporary test role","permissions":["platform_categories.read"]}');role_id:=(result->>'id')::uuid;
 perform public.platform_manage(root_user,'roles.delete',jsonb_build_object('id',role_id));assert not exists(select 1 from public.platform_roles where id=role_id), 'unused custom role removable';
 begin perform public.platform_assert_delegable(root_user,jsonb_build_array(jsonb_build_object('roleId','10000000-0000-4000-8000-000000000001','eventId',null)));raise exception 'root role delegated';exception when others then if sqlerrm<>'IAM_OWNER_PROTECTED' then raise;end if;end;
 begin perform public.platform_assert_delegable(root_user,jsonb_build_array(jsonb_build_object('roleId','10000000-0000-4000-8000-000000000002','eventId',gen_random_uuid())));raise exception 'event scope accepted';exception when others then if sqlerrm<>'IAM_EVENT_SCOPE' then raise;end if;end;
end$$;
select 'ok 5 - tenant permission rejection, root protection and custom role deletion';
rollback;
